// Independent LOCAL test encoder, not payment authority or deployed evidence.
// Intentionally uses explicit Borsh field order, not contract-generated bytes.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { test } from "node:test";

type QuoteVector = {
  quote_id: string; provider_id: string; recipient_id: string; service_id: string;
  category: string; quantity: number; price: string; asset: string; recurring: boolean;
  expires_at_ns: string; previous_quote_id: string | null; publisher_id: string; schema_version: number;
};
export const quoteVector: Readonly<QuoteVector> = Object.freeze({
  quote_id: "golden-quote", provider_id: "search", recipient_id: "provider.testnet",
  service_id: "search-batch", category: "search", quantity: 20,
  price: "9007199254740993", asset: "near-native", recurring: false,
  expires_at_ns: "50000", previous_quote_id: null,
  publisher_id: "provider.testnet", schema_version: 1,
});

function integer(value: bigint, bytes: number): Buffer {
  assert(value >= 0n && value < (1n << BigInt(bytes * 8)));
  const result = Buffer.alloc(bytes);
  for (let index = 0; index < bytes; index++) {
    result[index] = Number(value & 255n); // Only one bounded byte, never money.
    value >>= 8n;
  }
  return result;
}
function string(value: string): Buffer {
  const bytes = Buffer.from(value, "utf8");
  return Buffer.concat([integer(BigInt(bytes.length), 4), bytes]);
}
export function quoteBytes(
  vector: typeof quoteVector = quoteVector,
  domain = "runlatch.quote.v1", network = "testnet", contract = "contract.testnet",
): Buffer {
  return Buffer.concat([
    string(domain), string(network), string(contract),
    string(vector.quote_id), string(vector.provider_id), string(vector.recipient_id),
    string(vector.service_id), string(vector.category), integer(BigInt(vector.quantity), 4),
    integer(BigInt(vector.price), 16), string(vector.asset), Buffer.from([vector.recurring ? 1 : 0]),
    integer(BigInt(vector.expires_at_ns), 8),
    vector.previous_quote_id === null ? Buffer.from([0])
      : Buffer.concat([Buffer.from([1]), string(vector.previous_quote_id)]),
    string(vector.publisher_id), Buffer.from([vector.schema_version]),
  ]);
}
export function quoteHash(vector = quoteVector, domain?: string, network?: string, contract?: string): string {
  return createHash("sha256").update(quoteBytes(vector, domain, network, contract)).digest("hex");
}

test("Q-04 / T-02: independent LOCAL quote encoding binds every term and domain", () => {
  const canonical = quoteHash();
  for (const [field, changed] of Object.entries({
    quote_id: "other-quote", provider_id: "extract", recipient_id: "other.testnet",
    service_id: "other-service", category: "other-category", quantity: 19,
    price: "9007199254740994", asset: "unsupported", recurring: true,
    expires_at_ns: "50001", previous_quote_id: "older-quote",
    publisher_id: "other.testnet", schema_version: 2,
  })) {
    assert.notEqual(quoteHash({ ...quoteVector, [field]: changed }), canonical, field);
  }
  assert.notEqual(quoteHash(quoteVector, "other.domain"), canonical);
  assert.notEqual(quoteHash(quoteVector, undefined, "other-network"), canonical);
  assert.notEqual(quoteHash(quoteVector, undefined, undefined, "other.testnet"), canonical);
});

test("T-01: independent encoding preserves money above 2^53 as u128 little-endian", () => {
  assert.equal(integer(BigInt(quoteVector.price), 16).toString("hex"), "01000000000020000000000000000000");
  assert.throws(() => integer(-1n, 16));
  assert.throws(() => integer(1n << 128n, 16));
});

test("Q-04: independent Node bytes and hash match the shared Rust golden", () => {
  const golden = JSON.parse(readFileSync(new URL("../../fixtures/hashes/quote-v1.json", import.meta.url), "utf8"));
  assert.equal(golden.source, "LOCAL_HASH_FIXTURE_NOT_DEPLOYED");
  const vector: QuoteVector = { ...golden.terms.input, publisher_id: golden.terms.publisher_id, schema_version: golden.terms.schema_version };
  assert.equal(quoteBytes(vector, golden.domain, golden.network, golden.contract).toString("hex"), golden.expected_bytes_hex);
  assert.equal(quoteHash(vector, golden.domain, golden.network, golden.contract), golden.expected_hash);
});
